/* eslint-disable max-len */

'use strict';

// MODULES //

var isRowMajor = require( '@stdlib/ndarray/base/assert/is-row-major' );
var sfill = require( '@stdlib/blas/ext/base/sfill' ).ndarray;


// MAIN //

/**
* Generates a single-precision floating-point Vandermonde matrix.
*
* @private
* @param {integer} mode - mode indicating whether to generate increasing or decreasing powers
* @param {NonNegativeInteger} M - number of rows in `out` and number of indexed elements in `x`
* @param {NonNegativeInteger} N - number of columns in `out`
* @param {Float32Array} x - input array
* @param {integer} strideX - stride length for `x`
* @param {NonNegativeInteger} offsetX - starting index for `x`
* @param {Float32Array} out - output matrix
* @param {integer} strideOut1 - stride length for the first dimension of `out`
* @param {integer} strideOut2 - stride length for the second dimension of `out`
* @param {NonNegativeInteger} offsetOut - starting index for `out`
* @returns {Float32Array} output matrix
*
* @example
* var Float32Array = require( '@stdlib/array/float32' );
*
* var x = new Float32Array( [ 1.0, 2.0, 3.0 ] );
* var out = new Float32Array( 9 );
*
* svander( -1, 3, 3, x, 1, 0, out, 3, 1, 0 );
* // out => <Float32Array>[ 1.0, 1.0, 1.0, 4.0, 2.0, 1.0, 9.0, 3.0, 1.0 ]
*/
function svander( mode, M, N, x, strideX, offsetX, out, strideOut1, strideOut2, offsetOut ) {
	var isrm;
	var do0;
	var do1;
	var S0;
	var S1;
	var sx;
	var io;
	var ix;
	var i0;
	var i1;

	// Note on variable naming convention: S#, do#, io, i# where # corresponds to the loop number, with `0` being the innermost loop...
	isrm = isRowMajor( [ strideOut1, strideOut2 ] );
	sx = strideX;

	if ( isrm && mode > 0 ) {
		// Row-major, increasing: x^0, x^1, ..., x^(N-1)
		S0 = N;
		S1 = M;
		do0 = strideOut2;
		do1 = strideOut1 - ( S0*strideOut2 );
		io = offsetOut;
		ix = offsetX;
		for ( i1 = 0; i1 < S1; i1++ ) {
			out[ io ] = 1.0;
			io += do0;
			for ( i0 = 1; i0 < S0; i0++ ) {
				out[ io ] = out[ io - do0 ] * x[ ix ];
				io += do0;
			}
			ix += sx;
			io += do1;
		}
	} else if ( isrm ) {
		// Row-major, decreasing: x^(N-1), x^(N-2), ..., x^0
		S0 = N;
		S1 = M;
		do0 = strideOut2;
		do1 = strideOut1 + ( S0*strideOut2 );
		io = offsetOut + ( ( S0-1 ) * do0 );
		ix = offsetX;
		for ( i1 = 0; i1 < S1; i1++ ) {
			out[ io ] = 1.0;
			io -= do0;
			for ( i0 = 1; i0 < S0; i0++ ) {
				out[ io ] = out[ io + do0 ] * x[ ix ];
				io -= do0;
			}
			ix += sx;
			io += do1;
		}
	} else if ( mode > 0 ) {
		// Column-major, increasing: column j contains x^j
		S0 = M;
		S1 = N;
		do0 = strideOut1;
		do1 = strideOut2 - ( S0*strideOut1 );
		io = offsetOut;
		sfill( S0, 1.0, out, do0, io );
		io += strideOut2;
		for ( i1 = 1; i1 < S1; i1++ ) {
			ix = offsetX;
			for ( i0 = 0; i0 < S0; i0++ ) {
				out[ io ] = out[ io - strideOut2 ] * x[ ix ];
				ix += sx;
				io += do0;
			}
			io += do1;
		}
	} else {
		// Column-major, decreasing: column 0 contains x^(N-1), last column all ones
		S0 = M;
		S1 = N;
		sfill( S0, 1.0, out, strideOut1, offsetOut + ( ( S1-1 ) * strideOut2 ) );
		for ( i1 = S1 - 2; i1 >= 0; i1-- ) {
			io = offsetOut + ( i1 * strideOut2 );
			ix = offsetX;
			for ( i0 = 0; i0 < S0; i0++ ) {
				out[ io ] = out[ io + strideOut2 ] * x[ ix ];
				ix += sx;
				io += strideOut1;
			}
		}
	}
	return out;
}


// EXPORTS //

module.exports = svander;
